import React from 'react';

const Notifications = () => {
  return (
    <div className="p-8">
      <h2 className="text-xl font-semibold mb-4">Notifications</h2>
      <div className="bg-white p-6 rounded shadow">
        <p className="text-slate-600">No notifications yet.</p>
      </div>
    </div>
  );
};

export default Notifications;
